 INSERT
   INTO 
 	   TB_STATION 
 	   (
 	   STATION_NO
 	 , STATION_NAME
 	 , STATION_ADDRESS
 	 , STATION_TYPE
 	 , STATION_LNG
 	 , STATION_LAT
 	 , STATUS
 	   )
VALUES (
		  SEQ_SNO.NEXTVAL
		, #{stationName}
		, #{stationAddress}
		, #{stationType}
		, #{stationLng}
		, #{stationLat}
		, #{status}
		  )
